// ===== COA =====
// DEFAULT_COA dikosongkan — gunakan Import COA dari Sheets atau tambah manual
const DEFAULT_COA = [];

async function getAkun() {
  const saved = await KDB.getAll('akun');
  // Return saved COA (from import or manual), no auto-init
  if (saved && saved.length > 0) return saved.sort(function(a,b){ return a.kode.localeCompare(b.kode); });
  return [];
}

async function getAkunOptions(filter) {
  const akun = await getAkun();
  const filtered = filter ? akun.filter(function(a) {
    var kategori = (a && a.kategori) ? String(a.kategori) : '';
    var tipe = (a && a.tipe) ? String(a.tipe) : '';
    return kategori.includes(filter) || tipe === filter;
  }) : akun;
  return filtered.map(function(a) { return '<option value="' + a.kode + '">' + a.kode + ' - ' + a.nama + '</option>'; }).join('');
}

// ===== SEARCHABLE SELECT — auto-upgrade semua select akun =====
function upgradeToSearchableSelect(selectEl) {
  if (selectEl.dataset.upgraded) return;
  selectEl.dataset.upgraded = '1';

  // Tetap tampilkan select asli + tambah input search di atasnya
  var wrap = document.createElement('div');
  wrap.className = 'search-select-wrap';
  wrap.style.position = 'relative';
  selectEl.parentNode.insertBefore(wrap, selectEl);
  wrap.appendChild(selectEl);

  // Input search di atas select
  var input = document.createElement('input');
  input.className = 'ss-input';
  input.placeholder = '🔍 Ketik untuk cari akun...';
  input.style.cssText = 'width:100%;padding:5px 8px;border:1px solid #ccc;border-radius:4px;font-size:0.78rem;margin-bottom:3px;box-sizing:border-box';
  wrap.insertBefore(input, selectEl);

  // Simpan semua options asli
  var allOptions = [];
  for (var i = 0; i < selectEl.options.length; i++) {
    allOptions.push({ value: selectEl.options[i].value, text: selectEl.options[i].text, selected: selectEl.options[i].selected });
  }

  // Filter options saat user ketik
  input.addEventListener('input', function() {
    var q = input.value.toLowerCase();
    selectEl.innerHTML = '';
    allOptions.forEach(function(opt) {
      if (!q || opt.text.toLowerCase().includes(q) || opt.value.toLowerCase().includes(q)) {
        var o = document.createElement('option');
        o.value = opt.value;
        o.textContent = opt.text;
        selectEl.appendChild(o);
      }
    });
  });

  // Saat select berubah, update input
  selectEl.addEventListener('change', function() {
    var sel = selectEl.options[selectEl.selectedIndex];
    if (sel && sel.value) input.value = '';
  });

  // Tampilkan select dengan style normal
  selectEl.style.display = '';
  selectEl.style.width = '100%';
}

// Auto-upgrade selects periodically (untuk dynamic content)
setInterval(function() {
  document.querySelectorAll('select.j-akun, select.ej-akun, select.pc-akun, select[id="jurnal-filter-akun"], select[id="csv-bank-akun"], select[id="br-bank"]').forEach(function(sel) {
    if (!sel.dataset.upgraded && sel.options.length > 5) upgradeToSearchableSelect(sel);
  });
}, 1000);

function computeNeracaTotals(saldo, akunList, fdAkun) {
  var totalAset = 0, totalKewajiban = 0, totalEkuitas = 0;
  var totalPendapatan = 0, totalPendapatanLain = 0, totalBebanOps = 0, totalBebanLain = 0;
  var asetItems = [], kewajibanItems = [], ekuitasItems = [], pendapatanItems = [], bebanItems = [];

  // When akunList is provided, only iterate over official COA accounts.
  // This ensures phantom accounts from journal entries don't cause balance mismatches
  // between what computeNeracaTotals reports and what renderNeraca displays.
  var accountsToCheck = [];
  if (akunList && akunList.length > 0) {
    accountsToCheck = akunList.map(function(a) {
      return { kode: a.kode, kategori: a.kategori || '', nama: a.nama || a.kode };
    });
  } else {
    Object.keys(saldo).forEach(function(kode) {
      var s = saldo[kode];
      accountsToCheck.push({ kode: kode, kategori: (s.akun && s.akun.kategori) || '', nama: (s.akun && s.akun.nama) || kode });
    });
  }

  accountsToCheck.forEach(function(akun) {
    var kode = akun.kode;
    var s = saldo[kode];
    if (!s) return; // skip if no saldo data for this COA account
    var kat = akun.kategori;
    var katLower = kat.toLowerCase();
    var debit = s.debit || 0;
    var kredit = s.kredit || 0;
    var group = '';

    // Determine group based on kategori from COA
    if (kat.includes('Aset')) group = 'aset';
    else if (kat.includes('Kewajiban')) group = 'kewajiban';
    else if (kat === 'Ekuitas') group = 'ekuitas';
    else if (kat === 'Pendapatan Lain-lain') group = 'pendapatanLain';
    else if (kat === 'Pendapatan') group = 'pendapatan';
    else if (kat === 'Beban Operasional') group = 'bebanOps';
    else if (kat === 'Beban Lain-lain') group = 'bebanLain';
    else if (katLower.indexOf('ekuitas') !== -1 || katLower.indexOf('modal') !== -1) group = 'ekuitas';
    else if (katLower.indexOf('pendapatan') !== -1 || katLower.indexOf('revenue') !== -1) group = 'pendapatan';
    else if (katLower.indexOf('beban') !== -1 || katLower.indexOf('biaya') !== -1) group = 'bebanOps';
    else if (katLower.indexOf('kewajiban') !== -1 || katLower.indexOf('utang') !== -1 || katLower.indexOf('hutang') !== -1) group = 'kewajiban';
    else {
      // Final fallback: classify by account code prefix
      var prefix = (kode || '').charAt(0);
      if (prefix === '1') group = 'aset';
      else if (prefix === '2') group = 'kewajiban';
      else if (prefix === '3') group = 'ekuitas';
      else if (prefix === '4') group = 'pendapatan';
      else if (prefix === '5' || prefix === '6') group = 'bebanOps';
      else group = 'aset';
    }

    // Compute balance based on group normal direction (not s.akun.tipe)
    // Aset and Beban are debit-normal: balance = debit - kredit
    // Kewajiban, Ekuitas, Pendapatan are credit-normal: balance = kredit - debit
    var balance;
    if (group === 'aset' || group === 'bebanOps' || group === 'bebanLain') {
      balance = debit - kredit;
    } else {
      balance = kredit - debit;
    }

    var itemData = {kode: kode, nama: akun.nama, net: balance};

    if (group === 'aset') { totalAset += balance; asetItems.push(itemData); }
    else if (group === 'kewajiban') { totalKewajiban += balance; kewajibanItems.push(itemData); }
    else if (group === 'ekuitas') { totalEkuitas += balance; ekuitasItems.push(itemData); }
    else if (group === 'pendapatan') { totalPendapatan += balance; pendapatanItems.push(itemData); }
    else if (group === 'pendapatanLain') { totalPendapatanLain += balance; pendapatanItems.push(itemData); }
    else if (group === 'bebanOps') { totalBebanOps += balance; bebanItems.push(itemData); }
    else if (group === 'bebanLain') { totalBebanLain += balance; bebanItems.push(itemData); }
  });

  var labaBersih = totalPendapatan + totalPendapatanLain - totalBebanOps - totalBebanLain;

  // GUARANTEED BALANCE: Use prefix-based totals from ALL saldo entries
  // to ensure phantom accounts (in saldo but not in COA) are included.
  // From double-entry bookkeeping: sum of all (debit - kredit) = 0
  // Therefore: prefix1(d-k) = prefix2(k-d) + prefix3(k-d) + Laba Bersih
  var totalAsetAll = 0, totalKewAll = 0, totalEkuAll = 0;
  Object.keys(saldo).forEach(function(kode) {
    var s = saldo[kode];
    if (!s) return;
    var prefix = (kode || '').charAt(0);
    if (prefix === '1') totalAsetAll += ((s.debit || 0) - (s.kredit || 0));
    else if (prefix === '2') totalKewAll += ((s.kredit || 0) - (s.debit || 0));
    else if (prefix === '3') totalEkuAll += ((s.kredit || 0) - (s.debit || 0));
  });
  // Laba derived from accounting identity guarantees balance
  var labaBersihGuaranteed = totalAsetAll - totalKewAll - totalEkuAll;
  var totalKewEkuitas = totalKewAll + totalEkuAll + labaBersihGuaranteed;

  // labaCOA is the same as labaBersih when akunList is provided (since we already
  // iterated only over COA accounts). For backward compatibility, compute it separately
  // only when no akunList was provided (fallback mode using all saldo keys).
  var labaCOA = labaBersih;
  if (!akunList && fdAkun) {
    // In fallback mode, compute COA-only laba from fdAkun for comparison
    var pendapatanCOA = 0, bebanCOA = 0;
    (fdAkun || []).forEach(function(a) {
      var ss = saldo[a.kode];
      if (!ss) return;
      var d = ss.debit || 0, k = ss.kredit || 0;
      if (a.kategori === 'Pendapatan' || a.kategori === 'Pendapatan Lain-lain') pendapatanCOA += (k - d);
      else if (a.kategori === 'Beban Operasional' || a.kategori === 'Beban Lain-lain') bebanCOA += (d - k);
    });
    labaCOA = pendapatanCOA - bebanCOA;
  }

  return {
    totalAset: totalAsetAll, totalKewajiban: totalKewAll, totalEkuitas: totalEkuAll,
    totalPendapatan: totalPendapatan, totalPendapatanLain: totalPendapatanLain,
    totalBebanOps: totalBebanOps, totalBebanLain: totalBebanLain,
    labaBersih: labaBersihGuaranteed, labaCOA: labaCOA, totalKewEkuitas: totalKewEkuitas,
    asetItems: asetItems, kewajibanItems: kewajibanItems, ekuitasItems: ekuitasItems,
    pendapatanItems: pendapatanItems, bebanItems: bebanItems
  };
}

async function getFinancialData(targetYear) {
  var jurnal = await KDB.getAll('jurnal');
  var akun = await getAkun();
  var saldo = {};
  akun.forEach(function(a) { saldo[a.kode] = { akun: a, debit: 0, kredit: 0, net: 0 }; });

  // === SALDO AWAL: Tambahkan saldo awal tahun target ===
  var tahunSekarang = targetYear || new Date().getFullYear();
  var saldoAwalData = await KDB.getSetting('saldo_awal_' + tahunSekarang, {});

  Object.keys(saldoAwalData).forEach(function(kode) {
    var nominal = parseFloat(saldoAwalData[kode]) || 0;
    if (nominal === 0) return;
    if (!saldo[kode]) {
      var autoKat = autoKategoriCOA(kode, '', '');
      saldo[kode] = { akun: { kode: kode, nama: kode, kategori: autoKat.kategori, tipe: autoKat.tipe }, debit: 0, kredit: 0, net: 0 };
    }
    var tipe = saldo[kode].akun.tipe;
    var kat = (saldo[kode].akun.kategori || '').toLowerCase();
    var isDebitNormal = (tipe === 'Debit') ||
      kat.includes('aset') || kat.includes('beban') ||
      (kode.charAt(0) === '1') || (kode.charAt(0) === '5') || (kode.charAt(0) === '6');
    if (isDebitNormal) {
      saldo[kode].debit += nominal;
    } else {
      saldo[kode].kredit += nominal;
    }
  });

  // === JURNAL: Tambahkan transaksi jurnal pada TAHUN TARGET ===
  jurnal.filter(function(j) {
    var isNotPenutup = j.tipe !== 'penutup';
    var tglTahun = j.tanggal ? parseInt(j.tanggal.substring(0, 4)) : 0;
    return isNotPenutup && (tglTahun === tahunSekarang);
  }).forEach(function(j) {
    (j.lines || []).forEach(function(l) {
      if (!l.akun) return;
      if (!saldo[l.akun]) {
        var autoKat = autoKategoriCOA(l.akun, l.ket || '', '');
        saldo[l.akun] = { akun: { kode: l.akun, nama: l.ket || l.akun, kategori: autoKat.kategori, tipe: autoKat.tipe }, debit: 0, kredit: 0, net: 0 };
      }
      saldo[l.akun].debit += (parseFloat(l.debit) || 0);
      saldo[l.akun].kredit += (parseFloat(l.kredit) || 0);
    });
  });
  Object.values(saldo).forEach(function(s) {
    s.net = s.akun.tipe === 'Debit' ? s.debit - s.kredit : s.kredit - s.debit;
  });
  var allAkun = akun.slice();
  Object.keys(saldo).forEach(function(k) {
    if (!allAkun.find(function(a){ return a.kode === k; })) allAkun.push(saldo[k].akun);
  });
  allAkun.sort(function(a,b){ return (a.kode||'').localeCompare(b.kode||''); });
  return { saldo: saldo, akun: allAkun };
}

// ===== SHARED: Petty Cash Saldo from Collection =====
async function getPettyCashSaldo() {
  var pcSaldoAwal = parseFloat(await KDB.getSetting('pettycash_saldo', 0)) || 0;
  var pcTxList = await KDB.getAll('pettycash');
  var saldo = pcSaldoAwal;
  var tahunSkrg = new Date().getFullYear();
  pcTxList.forEach(function(p) {
    var tglTahun = p.tanggal ? parseInt(p.tanggal.substring(0, 4)) : 0;
    if (tglTahun !== tahunSkrg) return;
    var tipe = p.tipe || 'keluar';
    if (!p.tipe) {
      var ket2 = (p.keterangan || '').toLowerCase();
      if (ket2.includes('top up') || ket2.includes('isi kas') || (p.kategori || '').toLowerCase().includes('masuk')) tipe = 'masuk';
    }
    if (tipe === 'masuk') saldo += Math.abs(parseFloat(p.jumlah) || 0);
    else saldo -= Math.abs(parseFloat(p.jumlah) || 0);
  });
  return saldo;
}

function isKasBankAccount(akun) {
  if (!akun) return false;
  var nama = (akun.nama || '').toLowerCase();
  var kategori = (akun.kategori || '').toLowerCase();
  var kode = akun.kode || '';
  if (nama.includes('kas') || nama.includes('bank') || nama.includes('petty') || nama.includes('giro')) return true;
  if (kode.indexOf('1-11') === 0) return true;
  return kategori === 'aset lancar' && (nama.includes('deposito') || nama.includes('setara kas'));
}

function getKasBankAccounts(akunList) {
  var kasBank = (akunList || []).filter(isKasBankAccount);
  if (kasBank.length) return kasBank;
  return (akunList || []).filter(function(a) { return a.kategori === 'Aset Lancar'; });
}

// ===== DASHBOARD =====
async function renderDashboard() {
  if (KU.role === 'nanda') return renderPortalAset();
  // Auto-process items that reached their due date before calculating balance
  await autoJurnalJatuhTempo();

  if (KU.role === 'viewer' || KU.role === 'leader' || KU.role === 'bod') return renderDashboardApprover();
  const jurnal = await KDB.getAll('jurnal');
  const invoices = await KDB.getAll('invoice');
  const po = await KDB.getAll('po');
  const petty = await KDB.getAll('pettycash');
  const perusahaan = await KDB.getSetting('perusahaan', {});
  const allPD = await KDB.getAll('permohonan');
  const allDM = await KDB.getAll('danamasuk');
  // Saldo data
  const fd = await getFinancialData();
  const saldo = fd.saldo;
  const kasAkun = getKasBankAccounts(fd.akun);

  const totalDebit = jurnal.reduce(function(s,j){ return s+(parseFloat(j.totalDebit)||0); }, 0);
  const totalKredit = jurnal.reduce(function(s,j){ return s+(parseFloat(j.totalKredit)||0); }, 0);
  const unpaidInvoice = invoices.filter(function(i){ return i.status !== 'Lunas'; }).reduce(function(s,i){ return s+(parseFloat(i.total)||0); }, 0);
  const totalPO = po.reduce(function(s,p){ return s+(parseFloat(p.total)||0); }, 0);
  const totalPetty = petty.reduce(function(s,p){ return s+(parseFloat(p.jumlah)||0); }, 0);
  const pendingPD = allPD.filter(function(x){ return x.status && x.status.startsWith('Pending'); }).length;
  const pendingDM = allDM.filter(function(x){ return x.status && x.status.startsWith('Pending'); }).length;
  const recentJurnal = jurnal.slice().sort(function(a,b){ return (b.tanggal||'').localeCompare(a.tanggal||''); }).slice(0,5);

  const perusahaanBanner = perusahaan.nama
    ? '<div class="alert alert-info" style="margin-bottom:12px">🏢 <b>' + perusahaan.nama + '</b> — Periode: ' + (perusahaan.periode || new Date().getFullYear()) + '</div>'
    : '';
  const pendingBanner = (pendingPD + pendingDM) > 0
    ? '<div class="alert alert-warning">⏳ <b>' + (pendingPD+pendingDM) + '</b> transaksi menunggu approval. <a href="#" onclick="navigate(\'dana-approval\')" style="color:#e65100;font-weight:600">Buka Approval Center</a></div>'
    : '';

  const jurnalRows = recentJurnal.length
    ? recentJurnal.map(function(j){ return '<tr><td>'+fmtDate(j.tanggal)+'</td><td>'+( j.keterangan||'-')+'</td><td class="text-green">'+fmtRp(j.totalDebit)+'</td></tr>'; }).join('')
    : '<tr><td colspan="3" class="text-center text-muted">Belum ada transaksi</td></tr>';

  const approvedPD = allPD.filter(function(x){ return x.status === STATUS.APPROVED; }).slice(-3).map(function(p){
    var nameStr = (p.namaPemohon||'-');
    var words = nameStr.split(/\s+/);
    var initials = words.length >= 2 ? (words[0][0]||'') + (words[1][0]||'') : (words[0]||'').substring(0,2);
    initials = initials.toUpperCase();
    return '<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee;font-size:0.82rem"><span style="display:flex;align-items:center;gap:8px"><span style="width:28px;height:28px;border-radius:50%;background:#e2e8f0;display:flex;align-items:center;justify-content:center;font-size:0.7rem;font-weight:700;color:#475569;flex-shrink:0">' + initials + '</span>' + nameStr + ' — ' + (p.noPOInvoice||'-') + '</span><span style="background:#ecfdf5;color:#065f46;border-radius:12px;padding:3px 10px;font-size:0.73rem;font-weight:600">Approved</span></div>';
  }).join('');

  // Saldo cards — hanya Kas BNI, Mandiri, Petty Cash + pengeluaran/pendapatan hari ini
  var todayStr = today();
  var pengeluaranHariIni = 0, pendapatanHariIni = 0;
  jurnal.filter(function(j){ return j.tanggal === todayStr; }).forEach(function(j) {
    (j.lines || []).forEach(function(l) {
      var a = fd.akun.find(function(x){ return x.kode === l.akun; });
      if (a && (a.kategori||'').includes('Beban')) pengeluaranHariIni += l.debit || 0;
      if (a && (a.kategori||'').includes('Pendapatan')) pendapatanHariIni += l.kredit || 0;
    });
  });
  // Dashboard: hanya BNI, Mandiri, Petty Cash + pengeluaran/pendapatan hari ini
  var dashKasAkun = kasAkun.filter(function(a) {
    var n = (a.nama||'').toLowerCase();
    return n.includes('bni') || n.includes('mandiri') || n.includes('petty');
  });
  if (!dashKasAkun.length) dashKasAkun = kasAkun.slice(0, 3);

  // Hitung saldo petty cash dari collection (bukan dari jurnal) agar konsisten
  var pcSaldoReal = await getPettyCashSaldo();

  // Ambil saldo aktual bank untuk Mandiri (dan akun lainnya jika ada)
  var actualBalances = await getStoredBankActualBalances(dashKasAkun.map(function(a){ return a.kode; }));

  const saldoCards = dashKasAkun.map(function(a) {
    var net;
    // Untuk petty cash, pakai saldo dari collection (bukan jurnal)
    if ((a.nama||'').toLowerCase().includes('petty') || a.kode === '1-1101-3') {
      net = pcSaldoReal;
    } else {
      net = (saldo[a.kode] || {}).net || 0;
    }

    var actual = parseFloat(actualBalances[a.kode]) || 0;
    var selisih = net - actual;

    const bg = net > 0 ? '#f8fff8' : net < 0 ? '#fff8f8' : '#f8f9ff';
    const border = net > 0 ? '#10b981' : net < 0 ? '#f43f5e' : '#1a237e';
    const cls = net > 0 ? 'text-green' : net < 0 ? 'text-red' : 'text-blue';

    var selisihInfo = '';
    var sCls = Math.abs(selisih) < 1 ? 'text-green' : 'text-red';
    var actualText = actual > 0 ? fmtRp(actual) : 'Set Aktual';

    selisihInfo = '<div style="font-size:0.7rem;margin-top:4px;border-top:1px dashed #ddd;padding-top:4px;cursor:pointer" onclick="promptSetActualBalance(\'' + a.kode + '\', \'' + a.nama.replace(/'/g, "\\'") + '\')">'
      + '<span style="color:#64748b">Aktual:</span> <b style="color:#334155">' + actualText + '</b>'
      + (actual > 0 ? '<br><span style="color:#64748b">Selisih:</span> <b class="' + sCls + '">' + fmtRp(selisih) + '</b>' : '')
      + '</div>';

    return '<div class="stat-box" style="background:' + bg + ';border-radius:16px;padding:22px;border-left:6px solid ' + border + ';box-shadow:0 10px 15px -3px rgba(0,0,0,0.05);min-height:120px;cursor:pointer" onclick="navigate(\'monitor-buku-besar\')">'
      + '<div style="font-size:0.8rem;color:#64748b;font-weight:700;text-transform:uppercase;letter-spacing:0.05em">' + a.nama + '</div>'
      + '<div class="fw-bold ' + cls + '" style="font-size:1.65rem;margin-top:8px;word-break:break-word;line-height:1.1;letter-spacing:-0.02em">' + fmtRp(Math.abs(net)) + '</div>'
      + selisihInfo
      + '</div>';
  }).join('')
    + '<div class="stat-box red" style="padding:22px;border-left-width:6px;border-radius:16px;box-shadow:0 10px 15px -3px rgba(0,0,0,0.05);min-height:120px;cursor:pointer" onclick="navigate(\'jurnal-umum\')">'
    + '<div style="font-size:0.8rem;color:#64748b;font-weight:700;text-transform:uppercase;letter-spacing:0.05em">Pengeluaran Hari Ini</div>'
    + '<div class="fw-bold text-red" style="font-size:1.65rem;margin-top:8px;word-break:break-word;line-height:1.1;letter-spacing:-0.02em">' + fmtRp(pengeluaranHariIni) + '</div></div>'
    + '<div class="stat-box green" style="padding:22px;border-left-width:6px;border-radius:16px;box-shadow:0 10px 15px -3px rgba(0,0,0,0.05);min-height:120px;cursor:pointer" onclick="navigate(\'jurnal-umum\')">'
    + '<div style="font-size:0.8rem;color:#64748b;font-weight:700;text-transform:uppercase;letter-spacing:0.05em">Pendapatan Hari Ini</div>'
    + '<div class="fw-bold text-green" style="font-size:1.65rem;margin-top:8px;word-break:break-word;line-height:1.1;letter-spacing:-0.02em">' + fmtRp(pendapatanHariIni) + '</div></div>';
  const totalKasBank = kasAkun.reduce(function(s,a){
    if ((a.nama||'').toLowerCase().includes('petty') || a.kode === '1-1101-3') return s + pcSaldoReal;
    return s + (((saldo[a.kode]||{}).net)||0);
  }, 0);

  // Compute total pendapatan and pengeluaran for primary KPI
  var totalPendapatanKPI = 0, totalPengeluaranKPI = 0;
  jurnal.forEach(function(j) {
    (j.lines||[]).forEach(function(l) {
      var a = fd.akun.find(function(x){ return x.kode === l.akun; });
      if (a && (a.kategori||'').includes('Beban')) totalPengeluaranKPI += l.debit||0;
      if (a && (a.kategori||'').includes('Pendapatan')) totalPendapatanKPI += l.kredit||0;
    });
  });
  var labaRugi = totalPendapatanKPI - totalPengeluaranKPI;

  return '<div class="page-title" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:15px;margin-bottom:30px;padding:15px 0;border-bottom:1px solid #e2e8f0;font-size:2.1rem;font-weight:800;letter-spacing:-0.04em;color:#1a237e">'
    + '<span>🎯 Dashboard Keuangan</span>'
    + '</div>'
    + (perusahaanBanner ? '<div style="margin-bottom:20px;filter:drop-shadow(0 4px 6px rgba(0,0,0,0.05))">' + perusahaanBanner + '</div>' : '')
    + (pendingBanner ? '<div style="margin-bottom:25px;filter:drop-shadow(0 4px 6px rgba(0,0,0,0.05))">' + pendingBanner + '</div>' : '')

    + '<div class="responsive-grid-2" style="margin-bottom:25px">'
    + '<div class="stat-box green" style="padding:28px;border-left-width:6px;box-shadow:0 10px 15px -3px rgba(0,0,0,0.1);cursor:pointer" onclick="navigate(\'lap-saldo\')"><div class="val-large">' + fmtRp(totalKasBank) + '</div><div class="lbl" style="font-size:0.9rem;font-weight:700">Total Kas & Bank</div></div>'
    + '<div class="stat-box ' + (labaRugi >= 0 ? 'green' : 'red') + '" style="padding:28px;border-left-width:6px;box-shadow:0 10px 15px -3px rgba(0,0,0,0.1);cursor:pointer" onclick="navigate(\'lap-labarugi\')"><div class="val-large">' + fmtRp(labaRugi) + '</div><div class="lbl" style="font-size:0.9rem;font-weight:700">Laba/Rugi Berjalan</div></div>'
    + '</div>'

    + '<div class="stats-row" style="margin-bottom:25px">'
    + '<div class="stat-box" style="cursor:pointer" onclick="navigate(\'jurnal-umum\')"><div class="val">' + jurnal.length + '</div><div class="lbl">Total Jurnal</div></div>'
    + '<div class="stat-box orange" style="cursor:pointer" onclick="navigate(\'kalk-invoice\')"><div class="val">' + fmtRp(unpaidInvoice) + '</div><div class="lbl">Invoice Belum Lunas</div></div>'
    + '<div class="stat-box purple" style="cursor:pointer" onclick="navigate(\'kalk-po\')"><div class="val">' + fmtRp(totalPO) + '</div><div class="lbl">Total PO</div></div>'
    + '<div class="stat-box orange" style="cursor:pointer" onclick="navigate(\'dana-approval\')"><div class="val">' + (pendingPD+pendingDM) + '</div><div class="lbl">Pending Approval</div></div>'
    + '</div>'

    // Saldo Hari Ini — langsung di dashboard
    + '<div class="card" style="margin-bottom:25px;border-top:5px solid #1a237e"><div class="card-header" style="display:flex;justify-content:space-between;align-items:center"><div><h2>💵 Posisi Saldo Hari Ini</h2>'
    + '<span class="text-muted" style="font-size:0.8rem">' + new Date().toLocaleDateString('id-ID',{weekday:'long',year:'numeric',month:'long',day:'numeric'}) + '</span></div>'
    + '<button class="btn btn-sm btn-outline no-print" onclick="fixMandiriBalancePrompt()" style="font-size:0.72rem;padding:6px 12px;border-radius:10px;font-weight:700">⚙️ SET SALDO AKTUAL BANK</button></div>'
    + '<div class="saldo-grid">' + saldoCards + '</div>'
    + '<div style="margin-top:20px;padding-top:15px;border-top:1.5px solid #eee;display:flex;justify-content:space-between;align-items:center">'
    + '<span class="text-muted" style="font-size:0.9rem;font-weight:600">Total Kas & Bank (Sistem)</span>'
    + '<span class="fw-bold text-blue" style="font-size:1.4rem">' + fmtRp(totalKasBank) + '</span>'
    + '</div></div>'

    + '<div class="responsive-grid-2">'
    + '<div class="card"><div class="card-header"><h2>📝 Transaksi Terbaru</h2>' + (KU.role !== 'bod' ? '<button class="btn btn-sm btn-outline" onclick="navigate(\'jurnal-umum\')">Lihat Semua</button>' : '') + '</div>'
    + '<div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Keterangan</th><th>Debit</th></tr></thead><tbody>' + jurnalRows + '</tbody></table></div></div>'
    + '<div class="card"><div class="card-header"><h2>✅ Status Approval</h2><button class="btn btn-sm btn-outline" onclick="navigate(\'dana-approval\')">Buka</button></div>'
    + '<div class="stats-row" style="margin-bottom:0">'
    + '<div class="stat-box orange"><div class="val">' + pendingPD + '</div><div class="lbl">Permohonan Pending</div></div>'
    + '<div class="stat-box orange"><div class="val">' + pendingDM + '</div><div class="lbl">Dana Masuk Pending</div></div>'
    + '</div>' + (approvedPD ? '<div class="mt-8">' + approvedPD + '</div>' : '') + '</div>'
    + '</div>'
    + buildDashboardExtras(jurnal, fd, allPD, allDM)
    + (await renderPortalKomunikasiWidget());
}

// Auto-refresh dashboard setiap 30 detik
var _dashRefreshTimer = null;
function startDashAutoRefresh() {
  if (_dashRefreshTimer) clearInterval(_dashRefreshTimer);
  _dashRefreshTimer = setInterval(function() {
    if (currentSection === 'lap-dashboard') {
      renderSection('lap-dashboard');
    } else {
      clearInterval(_dashRefreshTimer);
      _dashRefreshTimer = null;
    }
  }, 300000); // 5 menit
}

