            var reason = 'Nominal ' + ratioMean.toFixed(1) + 'x di atas rata-rata ' + fmtRp(meanVal) + ' (ambang outlier ' + fmtRp(threshold) + ')';
            if (a.source) reason += ' | Sumber: ' + a.source;
            outliers.push(Object.assign({}, a, { reason: reason }));
