      + '</div>'
      + '<div style="flex:1">'
      + '<div style="background:#e0e0e0;border-radius:8px;height:16px;overflow:hidden">'
      + '<div style="width:' + healthScore + '%;height:100%;background:' + scoreColor + ';transition:width 0.5s"></div>'
