function buildATKItemRow() {
  return '<div class="pub-atk-row">'
    + '<div class="search-select-wrap" style="position:relative">'
    + '<input type="hidden" class="pub-atk-id" value="">'
    + '<input type="text" class="ss-input pub-input" placeholder="Cari Barang..." autocomplete="off" onfocus="openATKDropdown(this)" oninput="filterATKDropdown(this)" style="font-size:0.9rem">'
    + '<div class="ss-dropdown"></div>'
    + '</div>'
    + '<input type="number" class="pub-atk-qty" placeholder="Qty" min="1" value="1" style="width:100%; height:45px; padding:8px; border:1.5px solid #e2e8f0; border-radius:10px; font-size:1rem; text-align:center; box-sizing:border-box">'
    + '<button class="btn-del" onclick="this.closest(\'.pub-atk-row\').remove()">✕</button>'
    + '</div>';
}

function openATKDropdown(input) {
  var wrap = input.closest('.search-select-wrap');
  if (!wrap) return;
  renderATKDropdownItems(wrap, '');
  wrap.classList.add('open');
}

function filterATKDropdown(input) {
  var wrap = input.closest('.search-select-wrap');
  if (!wrap) return;
  var keyword = (input.value || '').toLowerCase();
  renderATKDropdownItems(wrap, keyword);
  wrap.classList.add('open');
}

function renderATKDropdownItems(wrap, keyword) {
  var dropdown = wrap.querySelector('.ss-dropdown');
  if (!dropdown) return;
  var list = window._atkList || [];
  var html = '';
  var count = 0;
  for (var i = 0; i < list.length; i++) {
    var item = list[i];
    var label = item.nama + ' (' + (item.satuan || 'pcs') + ')';
    if (keyword && label.toLowerCase().indexOf(keyword) === -1) continue;
    html += '<div class="ss-item" data-id="' + item.id + '" data-label="' + label.replace(/"/g, '&quot;') + '" onclick="selectATKItem(this)">' + label + '</div>';
    count++;
    if (count >= 50) break;
  }
  if (!html) html = '<div class="ss-item" style="color:#999;cursor:default">Tidak ditemukan</div>';
  dropdown.innerHTML = html;
}

function selectATKItem(el) {
  var wrap = el.closest('.search-select-wrap');
  if (!wrap) return;
  var id = el.getAttribute('data-id') || '';
  var label = el.getAttribute('data-label') || '';
  wrap.querySelector('.pub-atk-id').value = id;
  wrap.querySelector('.ss-input').value = label;
  wrap.classList.remove('open');
}

// Close ATK dropdowns when clicking outside
document.addEventListener('click', function(e) {
  if (!e.target.closest('.search-select-wrap')) {
    var openWraps = document.querySelectorAll('.search-select-wrap.open');
    for (var i = 0; i < openWraps.length; i++) {
      openWraps[i].classList.remove('open');
    }
  }
});

function previewPubFoto(input) {
  var el = document.getElementById('pub-foto-preview');
  if (!el || !input.files || !input.files[0]) return;
  var reader = new FileReader();
  reader.onload = function(e) {
    // Compress foto ke max 800px width dan quality 0.5 agar muat di Firestore (<1MB)
    var img = new Image();
    img.onload = function() {
      var canvas = document.createElement('canvas');
      var maxW = 800;
      var w = img.width, h = img.height;
      if (w > maxW) { h = h * maxW / w; w = maxW; }
      canvas.width = w; canvas.height = h;
      var ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0, w, h);
      var compressed = canvas.toDataURL('image/jpeg', 0.5);
      window._pubFotoData = compressed;
      el.innerHTML = '<img src="' + compressed + '" style="max-width:100%;max-height:200px;border-radius:8px;border:2px solid #4caf50;margin-top:4px">'
        + '<div style="font-size:0.75rem;color:#2e7d32;margin-top:4px">✅ Foto siap dikirim (' + Math.round(compressed.length/1024) + ' KB)</div>';
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(input.files[0]);
}

function tambahBarisPubATK() {
  var container = document.getElementById('pub-items-list');
  if (!container) return;
  var div = document.createElement('div');
  div.innerHTML = buildATKItemRow();
  container.appendChild(div.firstChild);
}

async function submitPubATKForm() {
  var pic = (document.getElementById('pub-pic')||{}).value||'';
  var tgl = (document.getElementById('pub-tgl')||{}).value||new Date().toISOString().split('T')[0];
  var ket = (document.getElementById('pub-ket')||{}).value||'';
  var linkBukti = (document.getElementById('pub-link-bukti')||{}).value||'';
  var fotoBukti = window._pubFotoData || '';
  var bukti = linkBukti || fotoBukti || '';
  var resultEl = document.getElementById('atk-form-result');
  if (!pic.trim()) { if (resultEl) resultEl.innerHTML = '<div style="background:#ffebee;color:#c62828;padding:10px 14px;border-radius:8px;margin-bottom:12px">Nama pengambil wajib diisi!</div>'; return; }
  var rows = document.querySelectorAll('.pub-atk-row');
  var items = [];
  rows.forEach(function(row) {
    var atkId = (row.querySelector('.pub-atk-id')||{}).value||'';
    var qty = parseInt((row.querySelector('.pub-atk-qty')||{}).value)||0;
    if (atkId && qty > 0) items.push({ atkId: atkId, qty: qty });
  });
  if (!items.length) { if (resultEl) resultEl.innerHTML = '<div style="background:#ffebee;color:#c62828;padding:10px 14px;border-radius:8px;margin-bottom:12px">Pilih minimal 1 item ATK!</div>'; return; }
  if (resultEl) resultEl.innerHTML = '<div style="background:#e3f2fd;color:#01579b;padding:10px 14px;border-radius:8px;margin-bottom:12px">Mengirim data...</div>';
  for (var i = 0; i < items.length; i++) {
    var item = items[i];
    var atkItem = (window._atkList||[]).find(function(x){ return x.id === item.atkId; });
    var logId = genId('ATKL');
    await KDB.save('atk_log', logId, { id: logId, atkId: item.atkId, tipe: 'keluar', qty: item.qty, harga: atkItem ? (parseFloat(atkItem.harga)||0) : 0, tanggal: tgl, pengambil: pic, keterangan: ket, buktiLink: linkBukti || fotoBukti || '', buktiPhoto: fotoBukti ? 'base64' : '', createdBy: 'public-form', createdAt: new Date().toISOString() });
  }
  if (resultEl) resultEl.innerHTML = '<div style="background:#e8f5e9;color:#2e7d32;padding:14px;border-radius:8px;margin-bottom:12px;font-weight:600">Form berhasil dikirim! Terima kasih, ' + pic + '.' + (bukti ? ' Bukti tersimpan.' : '') + '</div>';
  document.getElementById('pub-pic').value = '';
  document.getElementById('pub-ket').value = '';
  if (document.getElementById('pub-link-bukti')) document.getElementById('pub-link-bukti').value = '';
  if (document.getElementById('pub-foto-bukti')) document.getElementById('pub-foto-bukti').value = '';
  if (document.getElementById('pub-foto-preview')) document.getElementById('pub-foto-preview').innerHTML = '';
  window._pubFotoData = null;
  document.getElementById('pub-items-list').innerHTML = buildATKItemRow();
}

async function tambahATK() {
  var nama = (document.getElementById('atk-nama')||{}).value;
  if (!nama || !nama.trim()) { showAlert('Nama ATK wajib diisi!', 'danger'); return; }
  var id = genId('ATK');
  var kode = (document.getElementById('atk-kode')||{}).value || '-';
  await KDB.save('inventori_atk', id, {
    id: id,
    kode: kode.trim(),
    nama: nama.trim(),
    satuan: (document.getElementById('atk-satuan')||{}).value||'',
    stok: parseInt((document.getElementById('atk-stok')||{}).value)||0,
    beli: parseInt((document.getElementById('atk-beli')||{}).value)||0,
    pakai: parseInt((document.getElementById('atk-pakai')||{}).value)||0,
    harga: parseNominal((document.getElementById('atk-harga')||{}).value),
    createdBy: KU.username,
    createdAt: new Date().toISOString()
  });
  showAlert('ATK ditambahkan!');
  navigate('kalk-inventori-atk');
}

